5	/**
6	 * Computes the Soundex code of a name: the standard four-character phonetic encoding (an
7	 * initial letter followed by three digits) that maps similarly sounding surnames to the same
8	 * value. The owner {@code identityKey} folds {@code soundex(lastName)} into its hash (see
9	 * {@link OwnerIdentity}) and the soft-duplicate check compares surnames by this code (see
10	 * {@link AssignPossibleDuplicate}); centralising it here keeps that one primitive in one place.
11	 * It delegates to Apache Commons Codec's {@link Soundex} rather than re-implementing the
12	 * encoding. A blank or unencodable name yields the empty string.
13	 *
14	 * <p>A plain utility (not an OfficeFloor function), so it may expose helpers without
15	 * tripping the one-public-method-per-function rule.
16	 */
17	public final class NameSoundex {
18	
19	    private static final Soundex SOUNDEX = new Soundex();
20	
21	    private NameSoundex() {
22	    }
23	
24	    /**
25	     * @param name the name to encode; leading/trailing whitespace is ignored.
26	     * @return the four-character Soundex code, or the empty string when {@code name} is null,
27	     *         blank or contains no encodable letters.
28	     */
29	    public static String of(String name) {
30	        if (name == null || name.isBlank()) {
31	            return "";
32	        }
33	        try {
34	            return SOUNDEX.soundex(name.trim());
35	        }
36	        catch (IllegalArgumentException ex) {
37	            return ""; // a name with no encodable letters contributes no phonetic segment
38	        }
39	    }
40	}
